    "role": { "ai": "#1c69d4", "code": "#7b8594", "human": "#d9822b" },
    "evidence": { "A": "#2e9e6b", "B": "#7fb069", "C": "#e0a030", "D": "#d64545" }
  },
  "font": {
    "family": "Hanken Grotesk",
    "source": "https://fonts.google.com/specimen/Hanken+Grotesk (SIL Open Font License)",
    "weights": { "light": 300, "regular": 400, "medium": 500, "semibold": 600 }
  },
  "shape": { "radius": 0, "shadow": "none" },
